def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, DAILY_SALARY * 0.35)

    pressure_bids = []
    bob_bid = None
    cindy_bid = None
    urgent_opp_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            pressure_bids.append(float(pbid))
        if oid == 'Bob' and pbid is not None:
            bob_bid = float(pbid)
        if oid == 'Cindy' and pbid is not None:
            cindy_bid = float(pbid)
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1

    total_alive = len(alive)
    scarcity = supply <= 17
    abundant = supply >= 22

    if bob_bid is None:
        bob_bid = 75.0

    target = DAILY_SALARY * 0.45

    if scarcity:
        target = bob_bid + 2.0
    elif abundant:
        target = max(DAILY_SALARY * 0.32, bob_bid - 6.0)
    else:
        target = bob_bid + 0.5

    if cindy_bid is not None and cindy_bid >= 100:
        if hp >= 5 and no_water_days == 0:
            target = min(target, DAILY_SALARY * 0.42)
        elif hp <= 2 or no_water_days >= 1:
            target = max(target, DAILY_SALARY * 0.92)

    if urgent_opp_count >= 1 and scarcity:
        target += 3.0

    if total_alive >= 3 and scarcity:
        target += 2.0

    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.82)
    elif hp >= 8 and no_water_days == 0 and not scarcity:
        target = min(target, DAILY_SALARY * 0.5)

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            target = min(target, bob_bid + 1.0)
        else:
            target = max(target, DAILY_SALARY * 0.88)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 3 and hp >= 5:
        reserve_floor = DAILY_SALARY * 1.2
    elif days_left >= 1 and hp <= 3:
        reserve_floor = DAILY_SALARY * 0.2

    affordable = max(0.0, budget - reserve_floor)
    if affordable <= 0:
        affordable = budget

    bid = min(target, affordable, budget)
    if bid < 0:
        bid = 0.0

    if hp <= 2 and budget > 0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.95))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # If we have no budget, bid 0.
    if my_status['budget'] <= 0:
        return 0.0

    # Consider only alive opponents.
    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        # Conservative default: keep some budget for later.
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid'))

    # Estimate competitive pressure.
    # Alex/Cindy were around ~104-107 yesterday; we target just above their likely safe region.
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Health-based escalation.
    hp = my_status.get('hp', 0)

    # Supply-based adjustment: with higher supply, we can bid less.
    # supply range is [15,25]. Normalize to [0,1].
    s_norm = (supply - 15.0) / 10.0
    if s_norm < 0.0:
        s_norm = 0.0
    if s_norm > 1.0:
        s_norm = 1.0

    # Base bid fraction.
    if hp <= 2:
        frac = 0.90
    elif hp <= 4:
        frac = 0.75
    else:
        frac = 0.65

    # If yesterday pressure was high, slightly increase.
    # Use a soft cap so we don't overpay.
    if pressure >= DAILY_SALARY * 0.85:
        frac += 0.08
    elif pressure >= DAILY_SALARY * 0.70:
        frac += 0.03

    # Supply adjustment: higher supply -> bid less.
    frac -= 0.10 * s_norm

    # Clamp fraction.
    if frac < 0.35:
        frac = 0.35
    if frac > 0.98:
        frac = 0.98

    bid = my_status['budget']
    target = DAILY_SALARY * frac
    if target < bid:
        bid = target

    # Keep a small reserve to avoid bankruptcy late.
    reserve = DAILY_SALARY * 0.10
    if bid < reserve:
        bid = float(min(my_status['budget'], reserve))

    # Final clamp.
    if bid < 0.0:
        bid = 0.0
    if bid > my_status['budget']:
        bid = float(my_status['budget'])

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid very low to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0 # Ensure float for consistent math

    # Calculate remaining days
    remaining_days = EPISODE_DAYS - day_context['day']

    # --- Bidding Logic ---

    # 1. Desperation: Low HP or multiple days without water
    # Prioritize survival if HP is critical or missed water recently
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        # Bid very aggressively, aiming to outbid the highest opponent from yesterday
        return min(my_status['budget'], max(DAILY_SALARY * 0.95, highest_prev_bid + 1.5))

    # 2. End game aggression: If few days left, be more aggressive
    if remaining_days <= 3:
        # Increase bid to ensure water, considering opponent's past bids
        return min(my_status['budget'], max(DAILY_SALARY * 0.8, highest_prev_bid + 1.5))

    # 3. Normal / Mid-game strategy
    # Assess competition based on supply vs. total water needed (including self)
    total_water_needed_by_active_plus_me = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    # If supply is tight, competition is high
    if day_context['supply'] < total_water_needed_by_active_plus_me:
        # If opponents were bidding high yesterday, respond with a slightly higher bid
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            return min(my_status['budget'], highest_prev_bid + 1.5)
        # Otherwise, a strong but not desperate bid
        return min(my_status['budget'], DAILY_SALARY * 0.7)

    # If supply is relatively abundant
    else:
        # If opponents were bidding somewhat high, bid slightly above them to win cheaply
        if highest_prev_bid >= DAILY_SALARY * 0.5:
            return min(my_status['budget'], highest_prev_bid + 1.5)
        # If opponents were bidding low, or no strong signal, bid conservatively
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    # Fallback (should not be reached)
    return min(my_status['budget'], DAILY_SALARY * 0.5)

